/**
 * @planks("the user types {string} into the new-todo input and presses Enter")
 * @planks("the user toggles the checkbox on todo {string}")
 * @planks("the user clicks the toggle-all checkbox")
 * @planks("the user double-clicks the label of todo {string}")
 * @planks("the user types {string} in the edit input and presses Enter")
 * @planks("the user types {string} in the edit input and blurs")
 * @planks("the user types {string} in the edit input and presses Escape")
 * @planks("the user clicks the destroy button on todo {string}")
 * @planks("the user clicks the clear-completed button")
 * @planks("the user navigates to {string}")
 * @planks("the app is reloaded")
 */
(function () {
  'use strict';

  var STORAGE_KEY = 'todos-vanillajs';
  var newTodoInput = document.querySelector('.new-todo');
  var todoList = document.querySelector('.todo-list');
  var toggleAll = document.querySelector('.toggle-all');
  var todoCount = document.querySelector('.todo-count');
  var clearCompleted = document.querySelector('.clear-completed');
  var mainSection = document.querySelector('.main');
  var footer = document.querySelector('.footer');
  var filters = document.querySelector('.filters');

  function loadTodos() {
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];
    } catch (e) {
      return [];
    }
  }

  function saveTodos(todos) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function generateId() {
    return Date.now().toString(36) + Math.random().toString(36).slice(2);
  }

  function getRoute() {
    var hash = location.hash || '#/';
    if (hash === '#/active') return 'active';
    if (hash === '#/completed') return 'completed';
    return 'all';
  }

  function createTodoElement(todo) {
    var li = document.createElement('li');
    li.dataset.id = todo.id;
    if (todo.completed) li.classList.add('completed');

    li.innerHTML =
      '<div class="view">' +
        '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
        '<label>' + escapeHtml(todo.title) + '</label>' +
        '<button class="destroy"></button>' +
      '</div>' +
      '<input class="edit" value="' + escapeHtml(todo.title) + '">';

    return li;
  }

  function escapeHtml(str) {
    var div = document.createElement('div');
    div.textContent = str;
    return div.innerHTML;
  }

  function render() {
    var todos = loadTodos();
    var route = getRoute();

    // Filter todos for display
    var filtered = todos.filter(function (todo) {
      if (route === 'active') return !todo.completed;
      if (route === 'completed') return todo.completed;
      return true;
    });

    // Clear and rebuild list
    todoList.innerHTML = '';
    filtered.forEach(function (todo) {
      todoList.appendChild(createTodoElement(todo));
    });

    // Update counter
    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    var plural = activeCount === 1 ? 'item' : 'items';
    todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + plural + ' left';

    // Toggle all checkbox state
    toggleAll.checked = todos.length > 0 && activeCount === 0;

    // Show/hide main and footer
    if (todos.length === 0) {
      mainSection.style.display = 'none';
      footer.style.display = 'none';
    } else {
      mainSection.style.display = '';
      footer.style.display = '';
    }

    // Clear completed button visibility
    var completedCount = todos.filter(function (t) { return t.completed; }).length;
    clearCompleted.style.display = completedCount > 0 ? '' : 'none';

    // Update filter links
    var filterLinks = filters.querySelectorAll('a');
    filterLinks.forEach(function (a) {
      if (
        (route === 'all' && a.getAttribute('href') === '#/') ||
        (route === 'active' && a.getAttribute('href') === '#/active') ||
        (route === 'completed' && a.getAttribute('href') === '#/completed')
      ) {
        a.classList.add('selected');
      } else {
        a.classList.remove('selected');
      }
    });
  }

  function addTodo(title) {
    var trimmed = title.trim();
    if (!trimmed) return;
    var todos = loadTodos();
    todos.push({ id: generateId(), title: trimmed, completed: false });
    saveTodos(todos);
    newTodoInput.value = '';
    render();
  }

  function toggleTodo(id) {
    var todos = loadTodos();
    todos = todos.map(function (todo) {
      if (todo.id === id) {
        return Object.assign({}, todo, { completed: !todo.completed });
      }
      return todo;
    });
    saveTodos(todos);
    render();
  }

  function toggleAll() {
    var todos = loadTodos();
    var allCompleted = todos.every(function (t) { return t.completed; });
    todos = todos.map(function (todo) {
      return Object.assign({}, todo, { completed: !allCompleted });
    });
    saveTodos(todos);
    render();
  }

  function editTodo(id, newTitle) {
    var trimmed = newTitle.trim();
    var todos = loadTodos();
    if (!trimmed) {
      todos = todos.filter(function (t) { return t.id !== id; });
    } else {
      todos = todos.map(function (todo) {
        if (todo.id === id) {
          return Object.assign({}, todo, { title: trimmed });
        }
        return todo;
      });
    }
    saveTodos(todos);
    render();
  }

  function removeTodo(id) {
    var todos = loadTodos();
    todos = todos.filter(function (t) { return t.id !== id; });
    saveTodos(todos);
    render();
  }

  function clearCompletedTodos() {
    var todos = loadTodos();
    todos = todos.filter(function (t) { return !t.completed; });
    saveTodos(todos);
    render();
  }

  function findTodoId(li) {
    return li ? li.dataset.id : null;
  }

  // Event: new todo input
  newTodoInput.addEventListener('keydown', function (e) {
    if (e.key === 'Enter' || e.keyCode === 13) {
      addTodo(newTodoInput.value);
    }
  });

  // Event delegation on todo list
  todoList.addEventListener('click', function (e) {
    var li = e.target.closest('li');
    var id = findTodoId(li);
    if (!id) return;

    if (e.target.classList.contains('toggle')) {
      toggleTodo(id);
    } else if (e.target.classList.contains('destroy')) {
      removeTodo(id);
    }
  });

  // Double-click to edit
  todoList.addEventListener('dblclick', function (e) {
    var li = e.target.closest('li');
    if (!li) return;
    var label = e.target.closest('label');
    if (!label) return;

    li.classList.add('editing');
    var editInput = li.querySelector('.edit');
    editInput.focus();
  });

  // Edit input events
  todoList.addEventListener('keydown', function (e) {
    if (!e.target.classList.contains('edit')) return;
    var li = e.target.closest('li');
    var id = findTodoId(li);
    if (!id) return;

    if (e.key === 'Enter' || e.keyCode === 13) {
      li.classList.remove('editing');
      editTodo(id, e.target.value);
    } else if (e.key === 'Escape' || e.keyCode === 27) {
      li.classList.remove('editing');
      e.target.value = li.querySelector('label').textContent;
    }
  });

  todoList.addEventListener('blur', function (e) {
    if (!e.target.classList.contains('edit')) return;
    var li = e.target.closest('li');
    if (!li) return;
    // Only save if still in editing mode (not already handled by Enter/Escape)
    if (li.classList.contains('editing')) {
      var id = findTodoId(li);
      if (id) {
        li.classList.remove('editing');
        editTodo(id, e.target.value);
      }
    }
  }, true);

  // Toggle all
  toggleAll.addEventListener('click', function () {
    toggleAllChecked();
  });

  function toggleAllChecked() {
    var todos = loadTodos();
    var allCompleted = todos.length > 0 && todos.every(function (t) { return t.completed; });
    todos = todos.map(function (todo) {
      return Object.assign({}, todo, { completed: !allCompleted });
    });
    saveTodos(todos);
    render();
  }

  // Clear completed
  clearCompleted.addEventListener('click', function () {
    clearCompletedTodos();
  });

  // Filter links
  filters.addEventListener('click', function (e) {
    var a = e.target.closest('a');
    if (!a) return;
    // Let the hash change handle it
  });

  // Hash change for routing
  window.addEventListener('hashchange', function () {
    render();
  });

  // Initial render
  render();
})();

const { Given, When, Then } = require('@cucumber/cucumber');

const STORAGE_KEY = 'todos-vanillajs';

// ---------------------------------------------------------------------------
// Data-model helpers (operate on localStorage, not the DOM)
// ---------------------------------------------------------------------------

function loadTodos() {
  try {
    return JSON.parse(this.window.localStorage.getItem(STORAGE_KEY)) || [];
  } catch (e) {
    return [];
  }
}

function saveTodos(todos) {
  this.window.localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
}

function generateId() {
  return Date.now().toString(36) + Math.random().toString(36).slice(2);
}

function addTodoToModel(title) {
  const todos = loadTodos.call(this);
  todos.push({ id: generateId(), title: title.trim(), completed: false });
  saveTodos.call(this, todos);
  this.window.dispatchEvent(new this.window.Event('hashchange'));
}

function completeTodoInModel(title) {
  const todos = loadTodos.call(this);
  const updated = todos.map((t) =>
    t.title === title ? { ...t, completed: true } : t
  );
  saveTodos.call(this, updated);
  this.window.dispatchEvent(new this.window.Event('hashchange'));
}

function findTodoIdByTitle(title) {
  const todos = loadTodos.call(this);
  const todo = todos.find((t) => t.title === title);
  return todo ? todo.id : null;
}

// ---------------------------------------------------------------------------
// DOM helpers
// ---------------------------------------------------------------------------

function todoItems() {
  return Array.from(this.document.querySelectorAll('.todo-list li'));
}

function todoWithTitle(title) {
  return todoItems.call(this).find((li) => {
    const label = li.querySelector('.view label');
    return label && label.textContent === title;
  });
}

function newTodoInput() {
  return this.document.querySelector('.new-todo');
}

function toggleAllCheckbox() {
  return this.document.querySelector('.toggle-all');
}

function clearCompletedButton() {
  return this.document.querySelector('.clear-completed');
}

function todoCount() {
  const el = this.document.querySelector('.todo-count');
  return el ? el.textContent.trim() : '';
}

function mainSection() {
  return this.document.querySelector('.main');
}

function footerSection() {
  return this.document.querySelector('.footer');
}

function selectedFilter() {
  const a = this.document.querySelector('.filters .selected');
  return a ? a.textContent.trim() : '';
}

// ---------------------------------------------------------------------------
// Given
// ---------------------------------------------------------------------------

Given('the app is loaded', function () {
  // The Before hook in world.js already loaded the app. No-op.
});

Given('a todo {string} exists', function (title) {
  addTodoToModel.call(this, title);
});

Given('a completed todo {string} exists', function (title) {
  addTodoToModel.call(this, title);
  completeTodoInModel.call(this, title);
});

Given('the user navigates to {string}', function (hash) {
  this.navigate(hash);
});

// ---------------------------------------------------------------------------
// When
// ---------------------------------------------------------------------------

When(
  'the user types {string} into the new-todo input and presses Enter',
  function (text) {
    const input = newTodoInput.call(this);
    input.value = text;
    input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
    input.dispatchEvent(
      new this.window.KeyboardEvent('keydown', {
        key: 'Enter',
        keyCode: 13,
        bubbles: true,
      })
    );
  }
);

When('the user toggles the checkbox on todo {string}', function (title) {
  const li = todoWithTitle.call(this, title);
  if (!li) throw new Error(`No todo found with title "${title}"`);
  const checkbox = li.querySelector('.toggle');
  checkbox.click();
});

When('the user clicks the toggle-all checkbox', function () {
  const checkbox = toggleAllCheckbox.call(this);
  checkbox.click();
});

When(
  'the user double-clicks the label of todo {string}',
  function (title) {
    const li = todoWithTitle.call(this, title);
    if (!li) throw new Error(`No todo found with title "${title}"`);
    const label = li.querySelector('.view label');
    label.dispatchEvent(new this.window.Event('dblclick', { bubbles: true }));
  }
);

When(
  'the user types {string} in the edit input and presses Enter',
  function (text) {
    const editInput = this.document.querySelector('.todo-list li.editing .edit');
    if (!editInput) throw new Error('No editing input found');
    editInput.value = text;
    editInput.dispatchEvent(new this.window.Event('input', { bubbles: true }));
    editInput.dispatchEvent(
      new this.window.KeyboardEvent('keydown', {
        key: 'Enter',
        keyCode: 13,
        bubbles: true,
      })
    );
  }
);

When(
  'the user types {string} in the edit input and blurs',
  function (text) {
    const editInput = this.document.querySelector('.todo-list li.editing .edit');
    if (!editInput) throw new Error('No editing input found');
    editInput.value = text;
    editInput.dispatchEvent(new this.window.Event('input', { bubbles: true }));
    editInput.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
  }
);

When(
  'the user types {string} in the edit input and presses Escape',
  function (text) {
    const editInput = this.document.querySelector('.todo-list li.editing .edit');
    if (!editInput) throw new Error('No editing input found');
    editInput.value = text;
    editInput.dispatchEvent(new this.window.Event('input', { bubbles: true }));
    editInput.dispatchEvent(
      new this.window.KeyboardEvent('keydown', {
        key: 'Escape',
        keyCode: 27,
        bubbles: true,
      })
    );
  }
);

When(
  'the user clicks the destroy button on todo {string}',
  function (title) {
    const li = todoWithTitle.call(this, title);
    if (!li) throw new Error(`No todo found with title "${title}"`);
    const destroyBtn = li.querySelector('.destroy');
    destroyBtn.click();
  }
);

When('the user clicks the clear-completed button', function () {
  const btn = clearCompletedButton.call(this);
  btn.click();
});

When('the app is reloaded', function () {
  // Bridge localStorage and hash across happy-dom Window recreation.
  var savedStorage = null;
  try {
    savedStorage = this.window.localStorage.getItem(STORAGE_KEY);
  } catch (e) { /* no storage yet */ }
  var savedHash = null;
  try {
    savedHash = this.window.location.hash;
  } catch (e) { /* no hash */ }
  this.loadApp();
  try {
    if (savedStorage !== null) {
      this.window.localStorage.setItem(STORAGE_KEY, savedStorage);
    }
    if (savedHash && this.window.location.hash !== savedHash) {
      this.window.location.hash = savedHash;
    }
  } catch (e) { /* ignore */ }
  // Re-render by triggering the app's hashchange listener
  this.window.dispatchEvent(new this.window.Event('hashchange'));
});

// ---------------------------------------------------------------------------
// Then
// ---------------------------------------------------------------------------

Then('the todo list contains {int} item(s)', function (count) {
  const items = todoItems.call(this);
  if (items.length !== count) {
    throw new Error(
      `Expected ${count} items but found ${items.length}`
    );
  }
});

Then(
  'the todo at position {int} has title {string}',
  function (position, title) {
    const items = todoItems.call(this);
    const li = items[position - 1];
    if (!li) throw new Error(`No todo at position ${position}`);
    const label = li.querySelector('.view label');
    if (label.textContent !== title) {
      throw new Error(
        `Expected title "${title}" but found "${label.textContent}"`
      );
    }
  }
);

Then('the new-todo input is empty', function () {
  const input = newTodoInput.call(this);
  if (input.value !== '') {
    throw new Error(
      `Expected new-todo input to be empty but found "${input.value}"`
    );
  }
});

Then('todo {string} has the completed class', function (title) {
  const li = todoWithTitle.call(this, title);
  if (!li) throw new Error(`No todo found with title "${title}"`);
  if (!li.classList.contains('completed')) {
    throw new Error(`Todo "${title}" does not have the completed class`);
  }
});

Then('todo {string} does not have the completed class', function (title) {
  const li = todoWithTitle.call(this, title);
  if (!li) throw new Error(`No todo found with title "${title}"`);
  if (li.classList.contains('completed')) {
    throw new Error(`Todo "${title}" has the completed class`);
  }
});

Then('the toggle-all checkbox is checked', function () {
  const checkbox = toggleAllCheckbox.call(this);
  if (!checkbox.checked) {
    throw new Error('Toggle-all checkbox is not checked');
  }
});

Then('the toggle-all checkbox is not checked', function () {
  const checkbox = toggleAllCheckbox.call(this);
  if (checkbox.checked) {
    throw new Error('Toggle-all checkbox is checked');
  }
});

Then('todo {string} has the editing class', function (title) {
  const li = todoWithTitle.call(this, title);
  if (!li) throw new Error(`No todo found with title "${title}"`);
  if (!li.classList.contains('editing')) {
    throw new Error(`Todo "${title}" does not have the editing class`);
  }
});

Then(
  'the edit input for todo {string} contains {string}',
  function (title, expectedText) {
    const li = todoWithTitle.call(this, title);
    if (!li) throw new Error(`No todo found with title "${title}"`);
    const editInput = li.querySelector('.edit');
    if (editInput.value !== expectedText) {
      throw new Error(
        `Expected edit input to contain "${expectedText}" but found "${editInput.value}"`
      );
    }
  }
);

Then(
  'the edit input for todo {string} is focused',
  function (title) {
    const li = todoWithTitle.call(this, title);
    if (!li) throw new Error(`No todo found with title "${title}"`);
    const editInput = li.querySelector('.edit');
    if (this.document.activeElement !== editInput) {
      throw new Error(`Edit input for todo "${title}" is not focused`);
    }
  }
);

Then('todo {string} exists', function (title) {
  const li = todoWithTitle.call(this, title);
  if (!li) throw new Error(`No todo found with title "${title}"`);
});

Then('todo {string} does not exist', function (title) {
  const li = todoWithTitle.call(this, title);
  if (li) throw new Error(`Todo "${title}" still exists`);
});

Then('the counter shows {string}', function (expected) {
  const actual = todoCount.call(this);
  if (actual !== expected) {
    throw new Error(
      `Expected counter to show "${expected}" but found "${actual}"`
    );
  }
});

Then('the clear-completed button is hidden', function () {
  const btn = clearCompletedButton.call(this);
  const style = this.window.getComputedStyle(btn);
  if (style.display !== 'none') {
    throw new Error('Clear-completed button is visible');
  }
});

Then('the clear-completed button is visible', function () {
  const btn = clearCompletedButton.call(this);
  const style = this.window.getComputedStyle(btn);
  if (style.display === 'none') {
    throw new Error('Clear-completed button is hidden');
  }
});

Then('the main section is hidden', function () {
  const section = mainSection.call(this);
  const style = this.window.getComputedStyle(section);
  if (style.display !== 'none') {
    throw new Error('Main section is visible');
  }
});

Then('the main section is visible', function () {
  const section = mainSection.call(this);
  const style = this.window.getComputedStyle(section);
  if (style.display === 'none') {
    throw new Error('Main section is hidden');
  }
});

Then('the footer is hidden', function () {
  const footer = footerSection.call(this);
  const style = this.window.getComputedStyle(footer);
  if (style.display !== 'none') {
    throw new Error('Footer is visible');
  }
});

Then('the footer is visible', function () {
  const footer = footerSection.call(this);
  const style = this.window.getComputedStyle(footer);
  if (style.display === 'none') {
    throw new Error('Footer is hidden');
  }
});

Then('the selected filter is {string}', function (expected) {
  const actual = selectedFilter.call(this);
  if (actual !== expected) {
    throw new Error(
      `Expected selected filter to be "${expected}" but found "${actual}"`
    );
  }
});

const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  loadApp() {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // The app must EXECUTE, not merely be present. Two things were measured 2026-07-28 and both
    // bit an earlier version of this harness:
    //   1. happy-dom does NOT run scripts the parser sees — neither an appended <script> with
    //      textContent nor one inlined into document.write(). window.eval() DOES run them. An
    //      earlier harness looked green while app.js never ran, because its only assertion
    //      checked that the PAGE had loaded. A weak test hid a broken loader.
    //   2. DOMContentLoaded never fires from write()/close(), so an app that defers its init to
    //      DOMContentLoaded or window.load — the common TodoMVC shape — would never initialise
    //      and the harness would fail CORRECT code. The lifecycle events are dispatched here.
    // disableJavaScriptFileLoading stops the page's own src tag attempting a network fetch
    // (ECONNREFUSED under happy-dom, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
    return this.document;
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Measured 2026-07-28: a wave whose own world.js never
  // disposed reached 13.6G RSS across ~45 scenarios and was OOM-killed by the kernel, which
  // ended the suite with a bare "Killed" and no summary line. NODE_OPTIONS
  // --max-old-space-size does NOT prevent this: the growth is outside V8's old space, so the
  // cap bounds the JS heap while the process still takes the box down. Disposal is the fix.
  async disposeApp() {
    const w = this.window;
    if (!w) return;
    this.window = undefined;
    this.document = undefined;
