  if (!this._savedNodes) throw new Error('No saved nodes to compare');
  var currentNodes = todoItems.call(this).map((li) => li.dataset.id);
  if (this._savedNodes.length !== currentNodes.length) {
    throw new Error(
      `Expected ${this._savedNodes.length} nodes but found ${currentNodes.length}`
    );
  }
  for (var i = 0; i < this._savedNodes.length; i++) {
